# Let me solve this with a simple greedy/search approach
# Each subset must sum to 65

def solve_partition():
    numbers = list(range(1, 26))
    assignments = [-1] * 25
    subset_sums = [0] * 5

    # Try greedy with backtracking
    def backtrack(idx):
        if idx == 25:
            return all(s == 65 for s in subset_sums)

        num = numbers[idx]

        # Try assigning to each subset
        tried = set()
        for s in range(5):
            if subset_sums[s] in tried:
                continue
            if subset_sums[s] + num <= 65:
                tried.add(subset_sums[s])
                assignments[idx] = s
                subset_sums[s] += num
                if backtrack(idx + 1):
                    return True
                subset_sums[s] -= num
                assignments[idx] = -1

        return False

    # Sort numbers in descending order for better pruning
    numbers.sort(reverse=True)

    if backtrack(0):
        # Convert back to original indexing
        result = [0] * 25
        for i, num in enumerate(numbers):
            result[num - 1] = assignments[i]
        return result
    return None

result = solve_partition()
if result:
    print("Solution found:", result)
    # Verify
    subsets = [[] for _ in range(5)]
    for i, s in enumerate(result):
        subsets[s].append(i + 1)
    for s in range(5):
        print(f"Subset {s}: {subsets[s]}, sum = {sum(subsets[s])}")
else:
    print("No solution found")
